#include <stdio.h>
#include <string.h>

#define MAX_GATES 256

/* Same declarations as the candidate's file. */
enum gate_kind { GATE_BASIC, GATE_AND, GATE_OR };

struct gate {
    int kind;
    int input_count;
    int inputs[8];
};

/* Provided by the candidate in solution.c */
int smallest_cut_set(const struct gate *gates, int top);

static struct gate gates[MAX_GATES];

int main(void)
{
    int count;
    if (scanf("%d", &count) != 1 || count <= 0 || count > MAX_GATES) {
        return 1;
    }

    for (int i = 0; i < count; i++) {
        char kind[16];
        if (scanf("%15s", kind) != 1) {
            return 1;
        }
        if (strcmp(kind, "BASIC") == 0) {
            gates[i].kind = GATE_BASIC;
            gates[i].input_count = 0;
            continue;
        }
        gates[i].kind = (strcmp(kind, "AND") == 0) ? GATE_AND : GATE_OR;
        if (scanf("%d", &gates[i].input_count) != 1
            || gates[i].input_count < 1 || gates[i].input_count > 8) {
            return 1;
        }
        for (int j = 0; j < gates[i].input_count; j++) {
            if (scanf("%d", &gates[i].inputs[j]) != 1) {
                return 1;
            }
        }
    }

    int size = smallest_cut_set(gates, 0);
    printf("%d\n", size);
    if (size == 1) {
        printf("SINGLE POINT OF FAILURE\n");
    }
    return 0;
}
